steps.script:
var b = tree.root.find_child("DismissNudgeButton", true, false)
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
	return "dismissed"
return "absent"

var b = tree.root.find_child("ContinueButton", true, false)
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
return str(TutorialManager.current_step_id())

var out = "absent"
for n in tree.root.get_children():
	var s = n.get_script()
	if s == null or not str(s.resource_path).ends_with("EpicChallengeDialog.gd"):
		continue
	var q = [n]
	while not q.is_empty():
		var c = q.pop_front()
		if c is Button and str(c.text) == "Decline":
			c.pressed.emit()
			out = "declined"
			break
		for ch in c.get_children():
			q.append(ch)
return out

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var out = []
for a in d.assignments:
	out.append(str(a.get("weapon", "?")) + ":" + str((a.get("models", []) as Array).size()))
return ",".join(out)

